import { createHmac } from 'node:crypto';

import { test, expect, type Page } from '@playwright/test';

/**
 * Phase 2D.1 — notification centre mobile certification (375 / 390 / 412).
 *
 * Runs against the PRODUCTION build with the real backend behind the same-origin proxy, using a REAL
 * player who has real notifications generated by real cashier events. Nothing here is seeded through
 * the UI or faked.
 *
 * Proves: the bell is reachable on a phone, the list is server-backed, unread count is real, mark-read
 * and mark-all-read persist across a reload, states are honest, and there is no horizontal overflow.
 */

const EMAIL = process.env.NOTIF_EMAIL ?? '';
const PASSWORD = process.env.NOTIF_PASSWORD ?? '';

async function dismissIntro(page: Page) {
  const skip = page.getByRole('button', { name: /skip intro/i });
  try {
    if (await skip.isVisible({ timeout: 1000 })) { await skip.click(); await page.waitForTimeout(250); }
  } catch { /* none */ }
}


/**
 * Complete the two-factor challenge when the account has 2FA enabled.
 *
 * Phase 2D.2 made 2FA mandatory for administrator ACCOUNTS to use admin functions, so the seeded
 * operator now enrols and its login is genuinely two-step. `CERT_TOTP_SECRET` carries the shared
 * secret for the harness; without it the helper is a no-op for non-2FA accounts.
 */
/**
 * RFC-6238 TOTP, computed with `node:crypto` so this spec adds NO dependency to the frontend.
 * Used only to drive the login form; the server remains the sole verifier.
 */
function totp(base32Secret: string): string {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  let bits = '';
  for (const ch of base32Secret.replace(/=+$/, '').toUpperCase()) {
    const idx = alphabet.indexOf(ch);
    if (idx === -1) continue;
    bits += idx.toString(2).padStart(5, '0');
  }
  const bytes = Buffer.from((bits.match(/.{8}/g) ?? []).map((b) => parseInt(b, 2)));

  const counter = Buffer.alloc(8);
  counter.writeBigInt64BE(BigInt(Math.floor(Date.now() / 1000 / 30)));

  const hmac = createHmac('sha1', bytes).update(counter).digest();
  const offset = hmac[hmac.length - 1]! & 0x0f;
  const code =
    ((hmac[offset]! & 0x7f) << 24) |
    ((hmac[offset + 1]! & 0xff) << 16) |
    ((hmac[offset + 2]! & 0xff) << 8) |
    (hmac[offset + 3]! & 0xff);
  return String(code % 1_000_000).padStart(6, '0');
}

async function completeTwoFactor(page: Page) {
  const secret = process.env.CERT_TOTP_SECRET;
  const codeField = page.locator('#code');
  // `isVisible()` does NOT auto-wait — it answers immediately, so it would return false before the
  // challenge screen has rendered and the helper would skip the second factor entirely.
  const appeared = await codeField
    .waitFor({ state: 'visible', timeout: 8000 })
    .then(() => true)
    .catch(() => false);
  if (!appeared) return;
  if (!secret) throw new Error('login requires 2FA but CERT_TOTP_SECRET was not provided');

  await codeField.fill(totp(secret));
  const verify = page.getByRole('button', { name: /verify/i });
  await expect(verify).toBeEnabled({ timeout: 5000 }); // proves the controlled input took the value
  await verify.click();
}

async function login(page: Page) {
  await page.goto('/login', { waitUntil: 'domcontentloaded' });
  await dismissIntro(page);
  await page.locator('#email').fill(EMAIL);
  await page.locator('#password').fill(PASSWORD);
  await page.locator('button[type="submit"]').click();
  await completeTwoFactor(page);
  await page.waitForURL((u) => !u.pathname.startsWith('/login'), { timeout: 30_000 });
  await dismissIntro(page);
}

async function noOverflow(page: Page) {
  return page.evaluate(() => {
    const doc = document.documentElement;
    const scrollW = Math.max(doc.scrollWidth, document.body.scrollWidth);
    return { ok: scrollW <= doc.clientWidth + 1, scrollW, clientW: doc.clientWidth };
  });
}

test.describe('Phase 2D.1 — notification centre (mobile)', () => {
  test.skip(!EMAIL, 'no notification test account supplied (NOTIF_EMAIL)');

  test.beforeEach(async ({ context }) => {
    await context.addInitScript(() => {
      try { window.sessionStorage.setItem('gp-intro-seen', '1'); } catch { /* ignore */ }
    });
  });

  test('the bell is reachable on a phone and reaches the notification centre', async ({ page }, testInfo) => {
    const vp = testInfo.project.name;
    await login(page);
    await page.goto('/dashboard', { waitUntil: 'domcontentloaded' });
    await dismissIntro(page);

    const bell = page.getByTestId('notifications-bell');
    await expect(bell, `${vp}: bell visible at mobile width`).toBeVisible({ timeout: 15_000 });

    // Comfortable tap target on a touch device.
    const box = await bell.boundingBox();
    expect(box, `${vp}: bell has a box`).not.toBeNull();
    expect(box!.height, `${vp}: bell height >= 44px`).toBeGreaterThanOrEqual(44);
    expect(box!.width, `${vp}: bell width >= 44px`).toBeGreaterThanOrEqual(44);

    await bell.click();
    await page.waitForURL(/\/notifications/, { timeout: 15_000 });
    await expect(page.getByTestId('notifications-page')).toBeVisible({ timeout: 15_000 });
  });

  test('the list is server-backed and renders real notifications', async ({ page }, testInfo) => {
    const vp = testInfo.project.name;
    const calls: string[] = [];
    page.on('request', (r) => {
      if (r.url().includes('/api/')) calls.push(r.url().replace(/^https?:\/\/[^/]+/, '').split('?')[0]!);
    });

    await login(page);
    await page.goto('/notifications', { waitUntil: 'domcontentloaded' });
    await dismissIntro(page);

    await expect
      .poll(() => calls.some((c) => c.includes('/notifications')), { timeout: 20_000 })
      .toBe(true);

    // Real rows exist for this account (created by real cashier events).
    const rows = page.locator('[data-testid="notification-unread"], [data-testid="notification-read"]');
    await expect(rows.first(), `${vp}: at least one real notification renders`).toBeVisible({ timeout: 20_000 });
    expect(await rows.count(), `${vp}: multiple notifications`).toBeGreaterThan(0);

    const o = await noOverflow(page);
    expect(o.ok, `${vp}: no horizontal overflow (${o.scrollW} > ${o.clientW})`).toBe(true);
  });

  test('mark-read persists across a reload', async ({ page }, testInfo) => {
    const vp = testInfo.project.name;
    await login(page);
    await page.goto('/notifications', { waitUntil: 'domcontentloaded' });
    await dismissIntro(page);

    // `count()` does not auto-wait, so wait for the server-backed list to render before counting —
    // otherwise the assertion races the fetch and the test silently skips.
    const rows = page.locator('[data-testid="notification-unread"], [data-testid="notification-read"]');
    await expect(rows.first()).toBeVisible({ timeout: 20_000 });

    const unreadRows = page.locator('[data-testid="notification-unread"]');
    const before = await unreadRows.count();
    test.skip(before === 0, 'account has nothing unread to mark');

    await page.getByTestId('mark-read').first().click();
    await expect
      .poll(async () => unreadRows.count(), { timeout: 15_000 })
      .toBe(before - 1);

    await page.reload({ waitUntil: 'domcontentloaded' });
    await dismissIntro(page);
    await expect
      .poll(async () => unreadRows.count(), { timeout: 20_000, message: `${vp}: read state persisted` })
      .toBe(before - 1);
  });

  test('mark-all-read clears the badge and persists', async ({ page }, testInfo) => {
    const vp = testInfo.project.name;
    await login(page);
    await page.goto('/notifications', { waitUntil: 'domcontentloaded' });
    await dismissIntro(page);

    const markAll = page.getByTestId('mark-all-read');
    await expect(markAll).toBeVisible({ timeout: 15_000 });
    const box = await markAll.boundingBox();
    expect(box!.height, `${vp}: mark-all tap target >= 44px`).toBeGreaterThanOrEqual(44);

    if (await markAll.isEnabled()) {
      await markAll.click();
      await expect
        .poll(async () => page.locator('[data-testid="notification-unread"]').count(), { timeout: 15_000 })
        .toBe(0);

      await page.reload({ waitUntil: 'domcontentloaded' });
      await dismissIntro(page);
      await expect
        .poll(async () => page.locator('[data-testid="notification-unread"]').count(), { timeout: 20_000 })
        .toBe(0);
      // With nothing unread the header badge must be gone entirely — no permanent fake dot.
      await expect(page.getByTestId('unread-count')).toHaveCount(0);
    }
  });
});
